INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','infinitive-of-purpose','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"infinitive-of-purpose","title":"Infinitive of purpose","level":"A2","order":36,"summary":"Explain the aim of an action with to and the base form of a verb.","learningGoals":["Answering why","Keep the base form","Link the action and its aim"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"Answering why","explanation":"A to-infinitive can express an action’s purpose: the goal somebody intended. It answers a why question.","examples":["We stopped to admire the view.","She called to confirm the address."]},{"title":"Keep the base form","explanation":"Use to followed by the base verb, without an -ing ending. The subject of the main action can vary; the purpose verb stays in its base form.","examples":["They met to discuss the budget.","He met us to discuss the budget."]},{"title":"Link the action and its aim","explanation":"A short answer can begin with To. In a full sentence, place the purpose phrase after the main action. These tasks practise this to-infinitive pattern.","examples":["Why did you stop? To rest.","We stopped to rest."]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-infinitive-of-purpose"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."},"quizItems":[{"id":"e3bf7aed-3443-5b7f-ab42-edd2abde6fe5","topicSlug":"infinitive-of-purpose","level":"A2","prompt":"I opened the curtains ____ more daylight into the room. State the aim using the verb “let”.","choices":[{"id":"A","text":"for let"},{"id":"B","text":"to letting"},{"id":"C","text":"for to let"},{"id":"D","text":"to let"}],"answerId":"D","hint":"A to-infinitive can express an action’s purpose: the goal somebody intended. It answers a why question. Focus on **purpose form** in this question.","explanation":"The purpose is to let more daylight into the room. Use to plus the base verb.","keywords":[],"source":"seed","skill":"purpose-form","contextKey":"purpose-1","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-infinitive-of-purpose"],"version":"foundations-2026-09-v2","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"2cf4fc8c69822c0672dca05a2894d41b39747b964bff7a91c5f33cbc5cb2bc53","teaching":{"steps":["Identify what the question tests: **purpose form**. A to-infinitive can express an action’s purpose: the goal somebody intended. It answers a why question.","The purpose is to let more daylight into the room. Use to plus the base verb.","Choose **to let**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"For does not form the requested **to + base verb** purpose construction here. A for + -ing phrase can describe an object''s function in a different pattern. The purpose is to let more daylight into the room. Use to plus the base verb.","B":"This option uses an **-ing form** where the purpose infinitive needs a **base verb after to**. The purpose is to let more daylight into the room. Use to plus the base verb.","C":"For does not form the requested **to + base verb** purpose construction here. A for + -ing phrase can describe an object''s function in a different pattern. The purpose is to let more daylight into the room. Use to plus the base verb.","D":"The purpose is to let more daylight into the room. Use to plus the base verb."}}},{"id":"bd43eafa-5218-5b41-aec5-7e0dbb85010d","topicSlug":"infinitive-of-purpose","level":"A2","prompt":"I opened the curtains to ____ more daylight into the room. (let)","choices":[{"id":"A","text":"for let"},{"id":"B","text":"let"},{"id":"C","text":"letting"},{"id":"D","text":"to let"}],"answerId":"B","hint":"Use to followed by the base verb, without an -ing ending. The subject of the main action can vary; the purpose verb stays in its base form. Focus on **base after to** in this question.","explanation":"After the purpose marker to, the base form is let. Do not add another to or an -ing ending.","keywords":[],"source":"seed","skill":"base-after-to","contextKey":"purpose-1","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-infinitive-of-purpose"],"version":"foundations-2026-09-v2","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"8b5f11d66f53be7ac82605270e0e84705c6785c323485180d0c0fe3cb46218ad","teaching":{"steps":["Identify what the question tests: **base after to**. Use to followed by the base verb, without an -ing ending. The subject of the main action can vary; the purpose verb stays in its base form.","After the purpose marker to, the base form is let. Do not add another to or an -ing ending.","Choose **let**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"For does not form the requested **to + base verb** purpose construction here. A for + -ing phrase can describe an object''s function in a different pattern. After the purpose marker to, the base form is let. Do not add another to or an -ing ending.","B":"After the purpose marker to, the base form is let. Do not add another to or an -ing ending.","C":"This option uses an **-ing form** where the purpose infinitive needs a **base verb after to**. After the purpose marker to, the base form is let. Do not add another to or an -ing ending.","D":"The purpose construction requi